# Branchdial shell integration for bash. Generated by Branchdial; edits are overwritten.
#
# Bash is started as `bash --rcfile <this file> -i`, so it does not read your
# startup files by itself. We load them here, then add a prompt hook that
# reports the last exit code and the current directory to Branchdial through an
# invisible escape sequence (OSC 6973). Branchdial strips it from the screen.

# Login environment (on Git for Windows this sets PATH, MSYSTEM and the prompt).
if [ -f /etc/profile ]; then . /etc/profile; fi

if [ -f ~/.bash_profile ]; then
  . ~/.bash_profile
elif [ -f ~/.bashrc ]; then
  . ~/.bashrc
fi

# The nonce lets Branchdial ignore look-alike sequences printed by programs.
# It is not exported, so child processes never see it.
__rb_nonce="$BRANCHDIAL_NONCE"
unset BRANCHDIAL_NONCE

__rb_lastpwd=
__rb_cwd=
__rb_prompt() {
  local ec=$?
  if [ "$PWD" != "$__rb_lastpwd" ]; then
    __rb_lastpwd=$PWD
    # Git Bash: report a native Windows path. Only runs after a cd.
    case "$OSTYPE" in
      msys* | cygwin*) __rb_cwd=$(pwd -W 2>/dev/null || printf %s "$PWD") ;;
      *) __rb_cwd=$PWD ;;
    esac
  fi
  printf '\033]6973;P;%s;%s;%s\007' "$__rb_nonce" "$ec" "$__rb_cwd"
  return $ec
}

if [ -n "$__rb_nonce" ]; then
  # Run first so we see the real exit code, and hand it on to any existing hook.
  PROMPT_COMMAND="__rb_prompt${PROMPT_COMMAND:+;$PROMPT_COMMAND}"
fi
